import React, { useState, useRef, useEffect } from "react";
import { supabase } from "../lib/supabase";

/**
 * <Login />
 *
 * A full-screen access-code gate for MMS. Four separate digit cells instead
 * of a single password field, because the "code" here is a short shared
 * secret people will type from memory, not a password they'll paste from a
 * manager — the UI should look and feel like a keypad, not a login form.
 *
 * IMPORTANT — this is a visual/UX gate, not real security:
 * the correct code is checked in the browser (see CORRECT_CODE below), so
 * anyone who opens devtools can read it. Fine for keeping a private tool off
 * casual visitors; do NOT rely on this to protect anything sensitive. If you
 * need real access control, check the code against a server/edge function
 * (mark that call site with // CONNECT: as usual) instead of comparing
 * client-side.
 *
 * Usage:
 *   <Login onSuccess={() => setUnlocked(true)} />
 *
 * Optional props:
 *   persist   (bool, default true)  — remember a correct unlock for this
 *                                      browser tab session (sessionStorage),
 *                                      so a refresh doesn't re-prompt.
 *   storageKey (string, default "mms_session_unlocked")
 */

// Compact, pre-optimized PNG of the MMS mark, embedded so this file has zero
// external asset dependencies and drops into any project as-is.
const ICON_SRC =
  "data:image/png;base64,";

function friendlyError(err) {
  const msg = (err && err.message ? err.message : "").toLowerCase();
  if (msg.includes("invalid login credentials")) return "Incorrect email or password.";
  if (msg.includes("email not confirmed")) return "Confirm your email first, then sign in.";
  if (msg.includes("rate limit") || msg.includes("too many")) return "Too many attempts. Wait a minute and try again.";
  if (msg.includes("fetch") || msg.includes("network")) return "Can't reach the server. Check your connection.";
  return err && err.message ? err.message : "Couldn't sign in. Try again.";
}

export default function Login({ onSuccess }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [status, setStatus] = useState("idle"); // idle | busy | error | success
  const [message, setMessage] = useState("");
  const [shakeKey, setShakeKey] = useState(0);
  const emailRef = useRef(null);
  const pwRef = useRef(null);

  useEffect(() => {
    emailRef.current?.focus();
  }, []);

  const canSubmit =
    email.trim().length > 3 && password.length > 0 && status !== "busy" && status !== "success";

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!canSubmit) return;
    setStatus("busy");
    setMessage("");
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });
      if (error) throw error;
      setStatus("success");
      setMessage("Signed in.");
      onSuccess?.();
    } catch (err) {
      setStatus("error");
      setMessage(friendlyError(err));
      setShakeKey((k) => k + 1);
      setPassword("");
      requestAnimationFrame(() => pwRef.current?.focus());
    }
  };

  const clearError = () => {
    if (status === "error") {
      setStatus("idle");
      setMessage("");
    }
  };

  const hasError = status === "error";

  return (
    <div className="lg-root">
      <style>{CSS}</style>

      <div className="lg-glow" aria-hidden="true" />

      <form className="lg-panel" onSubmit={handleSubmit} noValidate>
        <img className="lg-mark" src={ICON_SRC} alt="MMS" />

        <h1 className="lg-title">Sign in</h1>
        <p className="lg-sub">This app is private. Sign in with your account to continue.</p>

        <div key={shakeKey} className={`lg-fields${hasError ? " lg-shake" : ""}`}>
          <label className="lg-label" htmlFor="lg-email">Email</label>
          <input
            id="lg-email"
            ref={emailRef}
            className={`lg-input${hasError ? " lg-input-error" : ""}`}
            type="email"
            inputMode="email"
            autoComplete="email"
            autoCapitalize="none"
            spellCheck={false}
            value={email}
            disabled={status === "success"}
            onChange={(e) => { setEmail(e.target.value); clearError(); }}
          />

          <label className="lg-label" htmlFor="lg-password">Password</label>
          <div className="lg-pwwrap">
            <input
              id="lg-password"
              ref={pwRef}
              className={`lg-input lg-input-pw${hasError ? " lg-input-error" : ""}${status === "success" ? " lg-input-success" : ""}`}
              type={showPw ? "text" : "password"}
              autoComplete="current-password"
              value={password}
              disabled={status === "success"}
              onChange={(e) => { setPassword(e.target.value); clearError(); }}
            />
            <button
              type="button"
              className="lg-eye"
              onClick={() => setShowPw((v) => !v)}
              aria-label={showPw ? "Hide password" : "Show password"}
              aria-pressed={showPw}
            >
              {showPw ? "Hide" : "Show"}
            </button>
          </div>
        </div>

        <div className={`lg-status${status === "success" ? " ok" : ""}`} role="status" aria-live="polite">
          {message}
        </div>

        <button type="submit" className="lg-unlock" disabled={!canSubmit}>
          {status === "busy" ? "Signing in…" : status === "success" ? "Signed in" : "Sign in"}
        </button>
      </form>
    </div>
  );
}

// ---------- scoped styles ----------
const CSS = `
.lg-root{
  --bg:#070b12; --bg-deep:#040609; --panel:#0d141f;
  --border:#1c2635; --text:#eef2f7; --muted:#7c8a9c;
  --brand:#0a4e9e; --brand-bright:#3d82f0; --brand-glow:rgba(61,130,240,.35);
  --danger:#e2665b; --danger-glow:rgba(226,102,91,.35);
  --success:#3ecf8e; --success-glow:rgba(62,207,142,.3);

  position:fixed; inset:0; z-index:1000;
  display:flex; align-items:center; justify-content:center;
  padding: max(24px, env(safe-area-inset-top,0px)) 20px max(24px, env(safe-area-inset-bottom,0px));
  background: var(--bg);
  color: var(--text);
  font-family:'Inter',system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing:antialiased;
  overflow:auto;
}
.lg-root *{box-sizing:border-box;}
.lg-root :focus-visible{outline:2px solid var(--brand-bright); outline-offset:3px;}

/* Slow, single ambient glow behind the mark — the one deliberate motion
   moment on this screen. Nothing else animates on its own. */
.lg-glow{
  position:absolute; width:640px; height:640px; border-radius:50%;
  top:50%; left:50%; transform:translate(-50%,-58%);
  background: radial-gradient(circle, var(--brand-glow) 0%, transparent 68%);
  filter: blur(10px);
  animation: lg-pulse 6s ease-in-out infinite;
  pointer-events:none;
}
@keyframes lg-pulse{
  0%,100%{ opacity:.55; transform:translate(-50%,-58%) scale(1); }
  50%{ opacity:.85; transform:translate(-50%,-58%) scale(1.06); }
}
@media (prefers-reduced-motion:reduce){
  .lg-glow{ animation:none; }
}

.lg-panel{
  position:relative; z-index:1;
  display:flex; flex-direction:column; align-items:center;
  width:100%; max-width:340px; text-align:center;
}

.lg-mark{
  width:84px; height:84px; margin-bottom:28px;
  filter: drop-shadow(0 10px 30px rgba(61,130,240,.35));
}

.lg-title{
  font-family:'Space Grotesk','Inter',system-ui,sans-serif;
  font-size:23px; font-weight:600; letter-spacing:-0.01em;
  margin:0 0 8px;
}
.lg-sub{
  font-size:13.5px; color:var(--muted); line-height:1.5;
  margin:0 0 34px; max-width:30ch;
}

.lg-cells{
  display:flex; gap:12px; margin-bottom:22px;
}
.lg-shake{ animation: lg-shake .5s cubic-bezier(.36,.07,.19,.97); }
@keyframes lg-shake{
  10%,90%{ transform:translateX(-1px); }
  20%,80%{ transform:translateX(2px); }
  30%,50%,70%{ transform:translateX(-4px); }
  40%,60%{ transform:translateX(4px); }
}
@media (prefers-reduced-motion:reduce){
  .lg-shake{ animation:none; }
}

.lg-cell{
  width:52px; height:60px;
  background:var(--panel);
  border:1.5px solid var(--border);
  border-radius:12px;
  color:var(--text);
  font-family:'Space Grotesk','Inter',monospace;
  font-size:26px; font-weight:600; text-align:center;
  font-variant-numeric:tabular-nums;
  caret-color:var(--brand-bright);
  transition: border-color .15s ease, box-shadow .15s ease, transform .1s ease;
}
.lg-cell:focus{
  border-color:var(--brand-bright);
  box-shadow:0 0 0 4px var(--brand-glow);
}
.lg-cell:not(:placeholder-shown){
  border-color:#2b3a4f;
}
.lg-cell-error{
  border-color:var(--danger) !important;
  box-shadow:0 0 0 4px var(--danger-glow) !important;
}
.lg-cell-success{
  border-color:var(--success) !important;
  box-shadow:0 0 0 4px var(--success-glow) !important;
  color:var(--success);
}

.lg-status{
  min-height:18px; font-size:12.5px; margin-bottom:18px;
  color:var(--danger);
}
.lg-cell-success ~ .lg-status,
.lg-status:has(+ .lg-unlock .lg-cell-success){ color:var(--success); }

.lg-unlock{
  width:100%; padding:13px; border-radius:12px; border:none;
  background:var(--brand); color:#eef4ff;
  font-family:'Inter',sans-serif; font-size:14.5px; font-weight:600;
  letter-spacing:.01em; cursor:pointer;
  transition: background .15s ease, transform .1s ease, opacity .15s ease;
  box-shadow:0 8px 24px -8px rgba(10,78,158,.6);
}
.lg-unlock:hover:not(:disabled){ background:var(--brand-bright); }
.lg-unlock:active:not(:disabled){ transform:scale(.98); }
.lg-unlock:disabled{ opacity:.45; cursor:not-allowed; box-shadow:none; }

@media (max-width:360px){
  .lg-cell{ width:46px; height:54px; font-size:22px; }
  .lg-cells{ gap:8px; }
}

/* ---------- Supabase email + password fields ---------- */
.lg-fields{ width:100%; text-align:left; margin-bottom:6px; }
.lg-label{
  display:block; font-size:12.5px; font-weight:500; color:var(--muted);
  margin:0 0 6px 2px;
}
.lg-fields .lg-label:not(:first-child){ margin-top:16px; }

.lg-input{
  width:100%; height:54px; padding:0 16px;
  background:var(--panel);
  border:1.5px solid var(--border);
  border-radius:12px;
  color:var(--text);
  font-family:'Inter',system-ui,sans-serif; font-size:15px;
  caret-color:var(--brand-bright);
  transition: border-color .15s ease, box-shadow .15s ease;
}
.lg-input:focus{
  outline:none;
  border-color:var(--brand-bright);
  box-shadow:0 0 0 4px var(--brand-glow);
}
.lg-input:disabled{ opacity:.7; }
.lg-input-error{
  border-color:var(--danger) !important;
  box-shadow:0 0 0 4px var(--danger-glow) !important;
}
.lg-input-success{
  border-color:var(--success) !important;
  box-shadow:0 0 0 4px var(--success-glow) !important;
}

.lg-pwwrap{ position:relative; }
.lg-input-pw{ padding-right:68px; }
.lg-eye{
  position:absolute; right:8px; top:50%; transform:translateY(-50%);
  height:38px; padding:0 12px; border:none; border-radius:9px;
  background:transparent; color:var(--muted);
  font-family:inherit; font-size:12.5px; font-weight:600; cursor:pointer;
  transition: color .15s ease, background .15s ease;
}
.lg-eye:hover{ color:var(--text); background:rgba(255,255,255,.05); }

.lg-status{ width:100%; text-align:center; margin-top:14px; }
.lg-status.ok{ color:var(--success); }
`;